pair q = point(g, b);

pair np = unit( rotate(slope) * dir(g,a));

pair nq = unit( rotate(0 - slope) * dir(g,b));

squig = squig .. p{np} .. q{nq};

}

squig = squig .. point(g, length(g)){unit(rotate(slope)*dir(g,length(g)))};

return squig;

}

